begin;
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
create table public.event_categories(id uuid primary key default gen_random_uuid(),name text not null unique check(char_length(btrim(name)) between 2 and 80),active boolean not null default true);
create table public.events(
 id uuid primary key default gen_random_uuid(),created_by uuid not null references public.profiles(id),
 title text not null check(char_length(btrim(title)) between 3 and 160),short_description text not null default '' check(char_length(short_description)<=500),description text not null default '' check(char_length(description)<=20000),
 category_id uuid references public.event_categories(id) on delete restrict,department text not null,venue text not null,contact text not null,
 starts_at timestamptz not null,ends_at timestamptz not null,registration_opens_at timestamptz not null,registration_closes_at timestamptz not null,cancellation_closes_at timestamptz not null,
 capacity integer not null check(capacity>0 and capacity<=100000),mode text not null default 'individual' check(mode in('individual','team')),min_team_size integer not null default 2,max_team_size integer not null default 5,
 fee numeric(10,2) not null default 0 check(fee>=0),waitlist_enabled boolean not null default false,eligible_departments text[] not null default '{}',eligible_years integer[] not null default '{}',require_roster boolean not null default false,
 certificate_enabled boolean not null default false,certificate_attendance_percent integer not null default 100 check(certificate_attendance_percent between 1 and 100),attendance_mode text not null default 'event' check(attendance_mode in('event','session')),attendance_finalized boolean not null default false,
 feedback_requires_attendance boolean not null default true,poster_path text,
 status text not null default 'draft' check(status in('draft','published','registration_closed','ongoing','completed','cancelled')),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 check(ends_at>starts_at),check(registration_closes_at>=registration_opens_at and registration_closes_at<=starts_at),check(cancellation_closes_at<=starts_at),check(min_team_size>=2 and max_team_size>=min_team_size and max_team_size<=50)
);
create index events_dates on public.events(starts_at,status);create index events_category on public.events(category_id);create index events_creator on public.events(created_by);create index events_search on public.events using gin(to_tsvector('simple',title||' '||short_description));
create table public.event_organizers(event_id uuid references public.events(id) on delete cascade,user_id uuid references public.profiles(id),primary key(event_id,user_id));create index event_organizers_user on public.event_organizers(user_id);
create table public.event_sessions(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,title text not null check(char_length(title) between 2 and 160),description text not null default '',starts_at timestamptz not null,ends_at timestamptz not null,venue text not null,speaker text not null default '',display_order integer not null default 0,unique(id,event_id),check(ends_at>starts_at));create index event_sessions_event on public.event_sessions(event_id);
create table public.student_roster(rrn text primary key check(rrn~'^[0-9]{12}$'),department text not null,study_year integer not null check(study_year between 1 and 6),active boolean not null,source_authority text not null check(char_length(source_authority)>=10),verified_by uuid not null references public.profiles(id),updated_at timestamptz not null default now());
create table public.teams(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id),name text not null check(char_length(btrim(name)) between 2 and 100),leader_id uuid not null references public.profiles(id),status text not null default 'draft' check(status in('draft','registered','cancelled')),created_at timestamptz not null default now(),unique(id,event_id),unique(event_id,name));create index teams_leader on public.teams(leader_id);
create table public.team_members(team_id uuid not null,event_id uuid not null,user_id uuid not null references public.profiles(id),status text not null check(status in('invited','accepted')),primary key(team_id,user_id),unique(event_id,user_id),foreign key(team_id,event_id) references public.teams(id,event_id) on delete cascade);create index team_members_user on public.team_members(user_id);
create table public.registrations(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id),user_id uuid not null references public.profiles(id),team_id uuid,reference text not null unique default upper(encode(extensions.gen_random_bytes(10),'hex')),status text not null check(status in('confirmed','waitlisted','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(event_id,user_id),unique(id,event_id),foreign key(team_id,event_id) references public.teams(id,event_id));create index registrations_user on public.registrations(user_id,created_at desc);create index registrations_capacity on public.registrations(event_id,status,created_at);create index registrations_team on public.registrations(team_id);
create table public.registration_history(id bigint generated always as identity primary key,registration_id uuid not null references public.registrations(id),old_status text,new_status text not null,actor_id uuid references public.profiles(id),created_at timestamptz not null default now());create index registration_history_registration on public.registration_history(registration_id);
create table public.checkin_tokens(registration_id uuid primary key references public.registrations(id),token_hash bytea not null unique,expires_at timestamptz not null);
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),event_id uuid references public.events(id),title text not null,message text not null,dedupe_key text not null,read_at timestamptz,created_at timestamptz not null default now(),unique(user_id,dedupe_key));create index notifications_user on public.notifications(user_id,created_at desc);
create table public.email_outbox(id uuid primary key default gen_random_uuid(),notification_id uuid not null unique references public.notifications(id),recipient text not null,payload jsonb not null,status text not null default 'pending' check(status in('pending','processing','delivered','failed')),retry_count integer not null default 0,next_attempt_at timestamptz not null default now(),lease_until timestamptz,lease_token uuid,last_error text,provider_id text,created_at timestamptz not null default now(),delivered_at timestamptz);create index email_outbox_due on public.email_outbox(status,next_attempt_at);
create table public.email_delivery_logs(id bigint generated always as identity primary key,job_id uuid not null references public.email_outbox(id),success boolean not null,error text,created_at timestamptz not null default now());create index email_delivery_job on public.email_delivery_logs(job_id);
create table public.attendance(id uuid primary key default gen_random_uuid(),registration_id uuid not null,event_id uuid not null,session_id uuid,checked_in_at timestamptz not null default now(),recorded_by uuid not null references public.profiles(id),present boolean not null default true,foreign key(registration_id,event_id) references public.registrations(id,event_id),foreign key(session_id,event_id) references public.event_sessions(id,event_id));create unique index attendance_event_unique on public.attendance(registration_id) where session_id is null;create unique index attendance_session_unique on public.attendance(registration_id,session_id) where session_id is not null;create index attendance_event on public.attendance(event_id);create index attendance_recorded_by on public.attendance(recorded_by);
create table public.attendance_corrections(id bigint generated always as identity primary key,attendance_id uuid not null references public.attendance(id),actor_id uuid not null references public.profiles(id),previous_present boolean not null,new_present boolean not null,reason text not null check(char_length(btrim(reason))>=10),created_at timestamptz not null default now());create index attendance_corrections_attendance on public.attendance_corrections(attendance_id);
create table public.certificate_templates(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 2 and 100),institution text not null check(char_length(institution)>=5),signatory_name text not null check(char_length(signatory_name)>=2),signatory_title text not null check(char_length(signatory_title)>=2),body text not null check(char_length(body) between 10 and 2000),approved_by uuid not null references public.profiles(id),active boolean not null default true,created_at timestamptz not null default now());
create table public.certificates(id uuid primary key default gen_random_uuid(),registration_id uuid not null references public.registrations(id),user_id uuid not null references public.profiles(id),event_id uuid not null references public.events(id),template_id uuid not null references public.certificate_templates(id),type text not null check(type in('participation','completion','achievement','winner','runner_up')),status text not null default 'pending' check(status in('pending','issued','revoked')),verification_id text not null unique default encode(extensions.gen_random_bytes(24),'hex'),object_path text,snapshot jsonb not null,approved_by uuid not null references public.profiles(id),approval_reason text not null,issued_at timestamptz,revoked_at timestamptz,revocation_reason text,created_at timestamptz not null default now(),unique(registration_id,type));create index certificates_user on public.certificates(user_id);create index certificates_event on public.certificates(event_id);
create table public.event_feedback(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id),user_id uuid not null references public.profiles(id),overall integer not null check(overall between 1 and 5),organization integer not null check(organization between 1 and 5),content integer not null check(content between 1 and 5),venue integer not null check(venue between 1 and 5),comments text not null default '' check(char_length(comments)<=3000),suggestions text not null default '' check(char_length(suggestions)<=3000),attend_future boolean,created_at timestamptz not null default now(),unique(event_id,user_id));create index feedback_user on public.event_feedback(user_id);
create table public.platform_settings(key text primary key,value jsonb not null,updated_by uuid not null references public.profiles(id),updated_at timestamptz not null default now());

create function private.can_manage(eid uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.is_active_verified() and (private.has_role('admin') or (private.has_role('organizer') and exists(select 1 from public.event_organizers where event_id=eid and user_id=auth.uid()))); $$;
create function public.event_state(e public.events) returns text language sql stable set search_path='' as $$select case when e.status in('draft','completed','cancelled') then e.status when now()>=e.starts_at then 'ongoing' when now()>e.registration_closes_at then 'registration_closed' else e.status end;$$;
create function private.require_actor() returns uuid language plpgsql stable security definer set search_path='' as $$begin if not private.is_active_verified() then raise exception 'Verified active account required' using errcode='42501';end if;return auth.uid();end;$$;
create function private.require_manager(eid uuid) returns void language plpgsql stable security definer set search_path='' as $$begin if not private.can_manage(eid) then raise exception 'Event access denied' using errcode='42501';end if;end;$$;
create function private.audit(action_name text,subject uuid,info jsonb default '{}') returns void language sql security definer set search_path='' as $$insert into public.audit_logs(actor_id,subject_id,action,details) values(auth.uid(),subject,action_name,info);$$;
create function private.notify(uid uuid,eid uuid,heading text,body text,key text) returns void language plpgsql security definer set search_path='' as $$declare nid uuid; ev public.events; ref text;begin
 insert into public.notifications(user_id,event_id,title,message,dedupe_key) values(uid,eid,heading,body,key) on conflict(user_id,dedupe_key) do nothing returning id into nid;
 if nid is not null then select * into ev from public.events where id=eid;select reference into ref from public.registrations where user_id=uid and event_id=eid;
 insert into public.email_outbox(notification_id,recipient,payload) select nid,email,jsonb_build_object('title',heading,'message',body,'event_title',ev.title,'starts_at',ev.starts_at,'venue',ev.venue,'event_id',eid,'reference',ref) from public.profiles where id=uid;end if;
end;$$;
create function private.eligible(e public.events,uid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles p join auth.users u on u.id=p.id left join public.student_roster r on r.rrn=p.rrn where p.id=uid and p.is_active and u.email_confirmed_at is not null and (u.banned_until is null or u.banned_until<=now()) and (not e.require_roster or r.active is true) and (cardinality(e.eligible_departments)=0 or coalesce(case when e.require_roster then r.department else p.department end,'')=any(e.eligible_departments)) and (cardinality(e.eligible_years)=0 or case when e.require_roster then r.study_year else p.study_year end=any(e.eligible_years)));$$;
create function private.attendance_percent(rid uuid) returns numeric language plpgsql stable security definer set search_path='' as $$declare e public.events; total integer; present integer;begin select ev.* into e from public.events ev join public.registrations r on r.event_id=ev.id where r.id=rid;
 if e.attendance_mode='event' then return case when exists(select 1 from public.attendance where registration_id=rid and session_id is null and public.attendance.present) then 100 else 0 end;end if;
 select count(*) into total from public.event_sessions where event_id=e.id;select count(*) into present from public.attendance where registration_id=rid and session_id is not null and public.attendance.present;
 return case when total=0 then 0 else present*100.0/total end;end;$$;
create function private.registration_changed() returns trigger language plpgsql security definer set search_path='' as $$begin if tg_op='INSERT' or new.status is distinct from old.status then
 insert into public.registration_history(registration_id,old_status,new_status,actor_id) values(new.id,case when tg_op='UPDATE' then old.status end,new.status,auth.uid());
 perform private.audit('registration.'||new.status,new.id,jsonb_build_object('event_id',new.event_id));
 perform private.notify(new.user_id,new.event_id,'Registration '||new.status,'Your registration is '||new.status||'. Reference: '||new.reference,'registration:'||new.id||':'||new.status||':'||new.updated_at);
 end if;return new;end;$$;
create trigger registration_change after insert or update of status on public.registrations for each row execute function private.registration_changed();

-- Every table uses RLS; browser writes are RPC-only. No permissive write policy.
do $$declare t text;begin foreach t in array array['event_categories','events','event_organizers','event_sessions','student_roster','teams','team_members','registrations','registration_history','checkin_tokens','notifications','email_outbox','email_delivery_logs','attendance','attendance_corrections','certificate_templates','certificates','event_feedback','platform_settings'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);end loop;end;$$;
grant select on public.event_categories,public.events,public.event_sessions to anon,authenticated;
create policy category_read on public.event_categories for select using(active or private.has_role('admin'));
create policy events_read on public.events for select using(status<>'draft' or private.can_manage(id));
create policy sessions_read on public.event_sessions for select using(exists(select 1 from public.events e where e.id=event_id and e.status<>'draft') or private.can_manage(event_id));
-- Anonymous public queries need only safe current-actor helper execution, not role tables.
grant usage on schema private to anon;
grant execute on function private.can_manage(uuid),private.has_role(public.app_role),private.is_active_verified() to anon,authenticated;

create function public.portal_public(resource text,args jsonb default '{}') returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;page_no integer:=greatest(0,least(coalesce((args->>'page')::integer,0),100000));begin
 if resource='categories' then select coalesce(jsonb_agg(to_jsonb(c) order by c.name),'[]') into result from public.event_categories c where active;
 elsif resource='events' then select jsonb_build_object('rows',coalesce(jsonb_agg(to_jsonb(q)),'[]'),'page',page_no) into result from(
 select e.*,c.name category_name,public.event_state(e) effective_status,(select count(*) from public.registrations r where r.event_id=e.id and r.status='confirmed') registered_count from public.events e left join public.event_categories c on c.id=e.category_id
 where e.status<>'draft' and (not(args?'id') or e.id=(args->>'id')::uuid) and (coalesce(args->>'search','')='' or to_tsvector('simple',e.title||' '||e.short_description)@@plainto_tsquery('simple',args->>'search')) and (coalesce(args->>'category_id','')='' or e.category_id=(args->>'category_id')::uuid) and (coalesce(args->>'department','')='' or e.department ilike '%'||(args->>'department')||'%') and (coalesce(args->>'date','')='' or (e.starts_at at time zone 'Asia/Kolkata')::date=(args->>'date')::date) and (coalesce(args->>'status','')='' or public.event_state(e)=args->>'status') and (coalesce(args->>'mode','')='' or e.mode=args->>'mode') and (coalesce((args->>'available')::boolean,false)=false or e.capacity>(select count(*) from public.registrations r where r.event_id=e.id and r.status='confirmed')) order by e.starts_at desc limit 20 offset page_no*20) q;
 elsif resource='sessions' then select coalesce(jsonb_agg(to_jsonb(s) order by s.display_order,s.starts_at),'[]') into result from public.event_sessions s join public.events e on e.id=s.event_id where e.id=(args->>'event_id')::uuid and e.status<>'draft';
 elsif resource='verify' then select jsonb_build_object('verification_id',verification_id,'status',status,'participant',snapshot->>'participant','event',snapshot->>'event','institution',snapshot->>'institution','type',type,'issued_at',issued_at,'revoked_at',revoked_at) into result from public.certificates where verification_id=args->>'id' and status in('issued','revoked');
 else raise exception 'Unknown public resource';end if;return result;end;$$;

-- Every registration/cancellation/promotion locks the same event row first.
create function private.promote_waitlist(eid uuid) returns void language plpgsql security definer set search_path='' as $$declare e public.events;r public.registrations;needed integer;free integer;begin
 select * into e from public.events where id=eid for update;
 if e.status not in('published','registration_closed') or now()>e.registration_closes_at then return;end if;
 for r in select * from public.registrations where event_id=eid and status='waitlisted' order by created_at,id loop
 if not exists(select 1 from public.registrations where id=r.id and status='waitlisted') then continue;end if;
 needed:=1;if r.team_id is not null then select count(*) into needed from public.registrations where team_id=r.team_id and status='waitlisted';end if;
 select e.capacity-count(*) into free from public.registrations where event_id=eid and status='confirmed';
 if needed>free then exit;end if;
 if exists(select 1 from public.registrations x where (x.id=r.id or (r.team_id is not null and x.team_id=r.team_id)) and x.status='waitlisted' and not private.eligible(e,x.user_id)) then continue;end if;
 update public.registrations set status='confirmed',updated_at=clock_timestamp() where (id=r.id or (r.team_id is not null and team_id=r.team_id)) and status='waitlisted';end loop;end;$$;

create function public.portal_command(operation text,payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=private.require_actor();eid uuid:=nullif(payload->>'event_id','')::uuid;rid uuid:=nullif(payload->>'registration_id','')::uuid;tid uuid:=nullif(payload->>'team_id','')::uuid;e public.events;r public.registrations;t public.teams;target uuid;row_id uuid;record_status text;seat_count integer;members uuid[];member uuid;token text;new_state text;previous text;a public.attendance;template public.certificate_templates;cert public.certificates;reason text;reply jsonb;
begin
 if operation='category_save' then
 if not private.has_role('admin') then raise exception 'Admin required' using errcode='42501';end if;
 if coalesce(payload->>'id','')='' then insert into public.event_categories(name) values(btrim(payload->>'name')) returning id into row_id;else update public.event_categories set name=btrim(payload->>'name'),active=coalesce((payload->>'active')::boolean,true) where id=(payload->>'id')::uuid returning id into row_id;end if;perform private.audit(operation,row_id);return jsonb_build_object('id',row_id);
 elsif operation='event_save' then
 if eid is null then if not(private.has_role('organizer') or private.has_role('admin')) then raise exception 'Organizer approval required' using errcode='42501';end if;
 insert into public.events(created_by,title,department,venue,contact,starts_at,ends_at,registration_opens_at,registration_closes_at,cancellation_closes_at,capacity)
 values(actor,payload->>'title',payload->>'department',payload->>'venue',payload->>'contact',(payload->>'starts_at')::timestamptz,(payload->>'ends_at')::timestamptz,(payload->>'registration_opens_at')::timestamptz,(payload->>'registration_closes_at')::timestamptz,(payload->>'cancellation_closes_at')::timestamptz,(payload->>'capacity')::integer) returning id into eid;
 insert into public.event_organizers values(eid,actor);
 else perform private.require_manager(eid);select * into e from public.events where id=eid for update;
 if e.status in('completed','cancelled') or e.attendance_finalized then raise exception 'Terminal/finalized event cannot be edited';end if;
 if exists(select 1 from public.registrations where event_id=eid and status<>'cancelled') and (e.mode is distinct from payload->>'mode' or e.min_team_size is distinct from coalesce((payload->>'min_team_size')::integer,2) or e.max_team_size is distinct from coalesce((payload->>'max_team_size')::integer,5) or e.attendance_mode is distinct from coalesce(payload->>'attendance_mode','event')) then raise exception 'Registration/attendance mode and team bounds are frozen after registrations';end if;
 if (payload->>'capacity')::integer<(select count(*) from public.registrations where event_id=eid and status='confirmed') then raise exception 'Capacity is below allocated seats';end if;end if;
 update public.events set title=btrim(payload->>'title'),short_description=coalesce(payload->>'short_description',''),description=coalesce(payload->>'description',''),category_id=nullif(payload->>'category_id','')::uuid,department=btrim(payload->>'department'),venue=btrim(payload->>'venue'),contact=btrim(payload->>'contact'),starts_at=(payload->>'starts_at')::timestamptz,ends_at=(payload->>'ends_at')::timestamptz,registration_opens_at=(payload->>'registration_opens_at')::timestamptz,registration_closes_at=(payload->>'registration_closes_at')::timestamptz,cancellation_closes_at=(payload->>'cancellation_closes_at')::timestamptz,capacity=(payload->>'capacity')::integer,
 mode=coalesce(payload->>'mode','individual'),min_team_size=coalesce((payload->>'min_team_size')::integer,2),max_team_size=coalesce((payload->>'max_team_size')::integer,5),waitlist_enabled=coalesce((payload->>'waitlist_enabled')::boolean,false),fee=coalesce((payload->>'fee')::numeric,0),certificate_enabled=coalesce((payload->>'certificate_enabled')::boolean,false),certificate_attendance_percent=coalesce((payload->>'certificate_attendance_percent')::integer,100),attendance_mode=coalesce(payload->>'attendance_mode','event'),feedback_requires_attendance=coalesce((payload->>'feedback_requires_attendance')::boolean,true),require_roster=coalesce((payload->>'require_roster')::boolean,false),eligible_departments=array(select jsonb_array_elements_text(coalesce(payload->'eligible_departments','[]'))),eligible_years=array(select jsonb_array_elements_text(coalesce(payload->'eligible_years','[]'))::integer),updated_at=now() where id=eid;
 perform private.audit(operation,eid);return jsonb_build_object('id',eid);
 elsif operation='event_transition' then perform private.require_manager(eid);select * into strict e from public.events where id=eid for update;new_state:=payload->>'status';
 if new_state='published' and e.status='draft' then
 if e.category_id is null or not exists(select 1 from public.event_categories where id=e.category_id and active) or char_length(btrim(e.description))<10 or char_length(btrim(e.venue))<2 or char_length(btrim(e.contact))<3 or char_length(btrim(e.department))<2 or e.registration_closes_at<=now() then raise exception 'Complete event details, active category and future registration close are required';end if;
 elsif new_state='completed' and e.status not in('draft','cancelled','completed') and now()>=e.ends_at then null;
 elsif new_state='registration_closed' and e.status='published' then null;
 elsif new_state='ongoing' and e.status in('published','registration_closed') and now()>=e.starts_at then null;
 elsif new_state='cancelled' and e.status not in('cancelled','completed') then if char_length(btrim(coalesce(payload->>'reason','')))<10 then raise exception 'Cancellation reason needs 10 characters';end if;
 else raise exception 'Invalid event state transition';end if;
 update public.events set status=new_state,updated_at=now() where id=eid;
 if new_state='cancelled' then update public.registrations set status='cancelled',updated_at=clock_timestamp() where event_id=eid and status<>'cancelled';update public.teams set status='cancelled' where event_id=eid;end if;
 perform private.audit('event.'||new_state,eid,jsonb_build_object('reason',payload->>'reason'));return jsonb_build_object('id',eid);
 elsif operation in('session_save','session_delete') then perform private.require_manager(eid);select * into strict e from public.events where id=eid for update;if e.attendance_finalized or e.status in('completed','cancelled') or exists(select 1 from public.attendance where event_id=eid) then raise exception 'Sessions are frozen after attendance starts';end if;
 row_id:=nullif(payload->>'id','')::uuid;
 if operation='session_delete' then delete from public.event_sessions where id=row_id and event_id=eid;return '{}';end if;
 if (payload->>'starts_at')::timestamptz<e.starts_at or (payload->>'ends_at')::timestamptz>e.ends_at then raise exception 'Session must be within event times';end if;
 if row_id is null then row_id:=gen_random_uuid();end if;
 if exists(select 1 from public.event_sessions where id=row_id and event_id<>eid) then raise exception 'Session access denied';end if;
