-- Internal functions are not client-callable; exposed RPCs independently authorize.
revoke all on all functions in schema private from public;
revoke all on function public.portal_command(text,jsonb) from public,anon;
grant execute on function public.portal_command(text,jsonb) to authenticated;
revoke all on function public.portal_public(text,jsonb) from public;
grant execute on function public.portal_public(text,jsonb) to anon,authenticated;
grant execute on function private.can_manage(uuid),private.has_role(public.app_role),private.is_active_verified() to anon,authenticated;
commit;
